    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] names = new String[n], actions = new String[n];
        for (int i = 0; i < n; i++) {
            names[i] = st.nextToken();
            actions[i] = st.nextToken();
        }
        List<List<String>> res = findViolations(names, actions);
        StringBuilder sb = new StringBuilder();
        for (List<String> part : res) sb.append(part.isEmpty() ? "NONE" : String.join(" ", part)).append("\n");
        System.out.print(sb);
    }
}
